def is_permutation_polynomial(a3, a1, p):
    """Checks if P(x) = a3*x^3 + a1*x is a permutation polynomial mod p."""
    values = set()
    for x in range(p):
        # Calculate P(x) mod p
        P_x = (a3 * (x**3) + a1 * x) % p
        if P_x in values:
            return False  # Not a permutation if value is repeated
        values.add(P_x)
    return True

p = 5
valid_pairs = []

# Iterate through all possible coefficients (0 to p-1)
for a3 in range(p):
    for a1 in range(p):
        if is_permutation_polynomial(a3, a1, p):
            valid_pairs.append((a3, a1))

print(f"Modulus p={p}")
print("Valid pairs (a3, a1) for P(x) = a3*x^3 + a1*x to be a PP mod 5:")
for pair in valid_pairs:
    print(pair)
print(f"Total valid pairs found: {len(valid_pairs)}")

